// Generates the app's colour tokens and the message key types.
//
//   node scripts/generate.mjs           write the files
//   node scripts/generate.mjs --check   fail if a committed file is stale (CI)
//
// Inputs:  brand/tokens/tokens.json (the single source of every colour value,
//          itself generated by brand/scripts/build.mjs) and src/messages/en.json.
// Outputs: src/tokens/brand.css   brand primitives as custom properties
//          src/tokens/theme.css   the app's semantic colours, light and dark
//          src/tokens/theme.json  the same colours resolved to hex, for code
//                                 that cannot read CSS (the Tauri window
//                                 background, the inline style in index.html)
//          src/messages/keys.ts   message keys and their placeholder types
//
// The semantic table below is the only place where app colours are decided
// (docs/APP-DESIGN.md, "Visual system" and "Direction: Daylight"). Components
// use the semantic custom properties only, never primitives or hex values.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const brandJson = join(root, "..", "..", "brand", "tokens", "tokens.json");
const check = process.argv.includes("--check");

const brand = JSON.parse(readFileSync(brandJson, "utf8"));
const HEADER =
  "Generated by packages/ui/scripts/generate.mjs from brand/tokens/tokens.json. Do not edit.";

// ---------------------------------------------------------------------------
// Brand primitives

/** @type {Map<string, string>} token path (e.g. "neutral.950") to #RRGGBB */
const primitives = new Map();
for (const scale of ["neutral", "emerald"]) {
  for (const [step, hex] of Object.entries(brand[scale])) {
    primitives.set(`${scale}.${step}`, hex);
  }
}
for (const [name, byTheme] of Object.entries(brand.semantic)) {
  primitives.set(`status.${name}.light`, byTheme.light);
  primitives.set(`status.${name}.dark`, byTheme.dark);
}
brand.gradient.markLight.forEach(([, hex], i) => primitives.set(`mark.light.${i}`, hex));
brand.gradient.mark.forEach(([, hex], i) => primitives.set(`mark.dark.${i}`, hex));

const cssVar = (path) => `--${path.replaceAll(".", "-")}`;

// ---------------------------------------------------------------------------
// Semantic app colours: [light (Daylight), dark (Ink)]
//
// A value is a primitive path, `alpha(path, a)` (the primitive at opacity a)
// or `mix(a, b, p)` (p of a, the rest b, in sRGB, like CSS color-mix()).

const alpha = (path, a) => ({ kind: "alpha", path, a });
const mix = (a, b, p) => ({ kind: "mix", a, b, p });

/** @type {Record<string, [unknown, unknown]>} */
const semantic = {
  // Surfaces. Daylight: grey chrome (#F6F6F7), white content. Ink: the content
  // is the brand's near-black, the chrome one step lighter.
  chrome: [mix("neutral.100", "neutral.50", 2 / 3), "neutral.900"],
  content: ["neutral.0", "neutral.950"],
  field: ["neutral.0", "neutral.950"],
  raised: ["neutral.0", "neutral.850"],
  // Hairlines: the only structure (APP-DESIGN #22).
  hairline: [alpha("neutral.950", 0.08), alpha("neutral.0", 0.08)],
  "hairline-strong": [alpha("neutral.950", 0.14), alpha("neutral.0", 0.14)],
  "window-border": ["neutral.300", "neutral.800"],
  // Text.
  text: ["neutral.950", "neutral.50"],
  "text-muted": ["neutral.600", "neutral.400"],
  "text-subtle": ["neutral.500", "neutral.500"],
  // Emerald means "alive": primary button, focus, selection, progress (#23).
  accent: ["emerald.700", "emerald.400"],
  "accent-hover": ["emerald.800", "emerald.300"],
  "accent-press": ["emerald.900", "emerald.200"],
  "on-accent": ["neutral.0", "emerald.950"],
  "accent-tint": [alpha("emerald.600", 0.1), alpha("emerald.400", 0.12)],
  focus: ["emerald.700", "emerald.400"],
  // Hover is a 4% overlay, press one more 4% step (#24).
  "overlay-hover": [alpha("neutral.950", 0.04), alpha("neutral.0", 0.04)],
  "overlay-press": [alpha("neutral.950", 0.08), alpha("neutral.0", 0.08)],
  // The close caption button turns red on hover, as everywhere on Windows.
  "caption-close": ["status.error.light", "status.error.light"],
  "caption-close-press": [
    mix("status.error.light", "neutral.950", 0.85),
    mix("status.error.light", "neutral.950", 0.85),
  ],
  "on-caption-close": ["neutral.0", "neutral.0"],
  // Status: small glyphs and fills only, text stays neutral (#23).
  success: ["status.success.light", "status.success.dark"],
  warning: ["status.warning.light", "status.warning.dark"],
  error: ["status.error.light", "status.error.dark"],
  info: ["status.info.light", "status.info.dark"],
  // The mark's gradient, one step darker on light (BRAND.md, Gradient).
  "mark-0": ["mark.light.0", "mark.dark.0"],
  "mark-1": ["mark.light.1", "mark.dark.1"],
  "mark-2": ["mark.light.2", "mark.dark.2"],
  // Progress (#23, #26): a quiet track; the fill is the mark's gradient while
  // a download runs, neutral grey once it stops.
  "progress-track": [alpha("neutral.950", 0.07), alpha("neutral.0", 0.08)],
  "progress-idle": ["neutral.400", "neutral.600"],
  // The details pane's file map (BRAND.md, "Pixels on the web"): a pale,
  // faintly green ground, squares along the emerald ramp, and the square a
  // connection is writing in deep ink (mint on dark).
  "map-empty": [alpha("emerald.900", 0.07), alpha("neutral.0", 0.07)],
  "map-0": ["emerald.400", "emerald.200"],
  "map-1": ["emerald.500", "emerald.300"],
  "map-2": ["emerald.600", "emerald.400"],
  "map-3": ["emerald.700", "emerald.500"],
  "map-head": ["emerald.950", "emerald.100"],
  "map-light": ["neutral.0", "neutral.0"],
  "map-depth": ["emerald.950", "neutral.950"],
  // Small tooltips drawn by the page (the file map's byte ranges).
  tooltip: ["neutral.900", "neutral.100"],
  "on-tooltip": ["neutral.50", "neutral.950"],
  // The one destructive button (deleting files from disk) and the scrim
  // behind the dialog that confirms it.
  danger: ["status.error.light", "status.error.light"],
  "danger-hover": [
    mix("status.error.light", "neutral.950", 0.88),
    mix("status.error.light", "neutral.950", 0.88),
  ],
  "on-danger": ["neutral.0", "neutral.0"],
  scrim: [alpha("neutral.950", 0.24), alpha("neutral.950", 0.56)],
  // Shadow colour for floating surfaces (elevation tokens in scale.css).
  shadow: [alpha("neutral.950", 0.12), alpha("neutral.950", 0.48)],
};

function toCss(value) {
  if (typeof value === "string") return `var(${cssVar(value)})`;
  if (value.kind === "alpha") {
    return `color-mix(in srgb, var(${cssVar(value.path)}) ${pct(value.a)}, transparent)`;
  }
  return `color-mix(in srgb, var(${cssVar(value.a)}) ${pct(value.p)}, var(${cssVar(value.b)}))`;
}

function pct(x) {
  return `${Number((x * 100).toFixed(2))}%`;
}

function rgb(path) {
  const hex = primitives.get(path);
  if (!hex) throw new Error(`unknown brand token: ${path}`);
  return [1, 3, 5].map((i) => Number.parseInt(hex.slice(i, i + 2), 16));
}

const h2 = (n) => Math.round(n).toString(16).padStart(2, "0").toUpperCase();

/** Resolves a value to #RRGGBB or #RRGGBBAA, the way the browser does. */
function toHex(value) {
  if (typeof value === "string") return primitives.get(value) ?? fail(value);
  if (value.kind === "alpha") {
    return `#${rgb(value.path).map(h2).join("")}${h2(value.a * 255)}`;
  }
  const a = rgb(value.a);
  const b = rgb(value.b);
  return `#${a.map((c, i) => h2(c * value.p + b[i] * (1 - value.p))).join("")}`;
}

function fail(path) {
  throw new Error(`unknown brand token: ${path}`);
}

// ---------------------------------------------------------------------------
// Outputs

const outputs = new Map();

{
  const lines = [`/* ${HEADER} */`, ":root {"];
  for (const [path, hex] of primitives) lines.push(`  ${cssVar(path)}: ${hex};`);
  lines.push(`  --motion-arrive-duration: ${brand.motion.dur}s;`);
  lines.push(`  --motion-arrive-stagger: ${brand.motion.stagger}s;`);
  // The rise: the first keyframe interval of the brand loop (0.15 -> 1).
  const rise = Number((brand.motion.dur * brand.motion.keyTimes[1]).toFixed(3));
  lines.push(`  --motion-arrive-rise: ${rise}s;`);
  lines.push(`  --motion-arrive-rest: ${brand.motion.values[0]};`);
  lines.push("}", "");
  outputs.set("src/tokens/brand.css", lines.join("\n"));
}

{
  const lines = [
    `/* ${HEADER} */`,
    "/* light-dark() follows color-scheme, which theme.ts sets from the Theme",
    "   setting: data-theme on <html> for Light or Dark, the OS for System. */",
    ":root {",
  ];
  for (const [name, [light, dark]] of Object.entries(semantic)) {
    lines.push(`  --color-${name}: light-dark(${toCss(light)}, ${toCss(dark)});`);
  }
  lines.push("}", "");
  outputs.set("src/tokens/theme.css", lines.join("\n"));
}

{
  const resolved = { light: {}, dark: {} };
  for (const [name, [light, dark]] of Object.entries(semantic)) {
    resolved.light[name] = toHex(light);
    resolved.dark[name] = toHex(dark);
  }
  outputs.set("src/tokens/theme.json", `${JSON.stringify(resolved, null, 2)}\n`);
}

{
  const messages = JSON.parse(readFileSync(join(root, "src", "messages", "en.json"), "utf8"));
  const lines = [
    `// Generated by packages/ui/scripts/generate.mjs from src/messages/en.json. Do not edit.`,
    "",
    "/** Placeholder values each message needs; `never` means none. */",
    "export interface MessageParams {",
  ];
  for (const [key, value] of Object.entries(messages)) {
    const plural = typeof value === "object";
    const texts = plural ? Object.values(value) : [value];
    const names = new Set();
    for (const text of texts) {
      for (const m of text.matchAll(/\{(\w+)\}/g)) names.add(m[1]);
    }
    if (plural) names.add("count");
    const fields = [...names]
      .sort()
      .map((n) => `${n}: ${n === "count" ? "number" : "string | number"}`);
    lines.push(
      `  ${JSON.stringify(key)}: ${fields.length ? `{ ${fields.join("; ")} }` : "never"};`,
    );
  }
  lines.push("}", "");
  outputs.set("src/messages/keys.ts", lines.join("\n"));
}

let stale = 0;
for (const [rel, content] of outputs) {
  const path = join(root, rel);
  let current = null;
  try {
    current = readFileSync(path, "utf8").replaceAll("\r\n", "\n");
  } catch {
    // Missing: stale in --check, written otherwise.
  }
  if (current === content) continue;
  if (check) {
    console.error(`stale: packages/ui/${rel}`);
    stale += 1;
  } else {
    writeFileSync(path, content);
    console.log(`wrote packages/ui/${rel}`);
  }
}
if (stale) {
  console.error("Run `pnpm --filter @boltget/ui generate` and commit the result.");
  process.exit(1);
}
